/// <summary>
/// This class can be used to analyse audio data.
///
/// ```js
/// // create an AudioListener and add it to the camera
/// const listener = new THREE.AudioListener();
/// camera.add( listener );
///
/// // create an Audio source
/// const sound = new THREE.Audio( listener );
///
/// // load a sound and set it as the Audio object's buffer
/// const audioLoader = new THREE.AudioLoader();
/// audioLoader.load( 'sounds/ambient.ogg', function( buffer ) {
/// 	sound.setBuffer( buffer );
/// 	sound.setLoop(true);
/// 	sound.setVolume(0.5);
/// 	sound.play();
/// });
///
/// // create an AudioAnalyser, passing in the sound and desired fftSize
/// const analyser = new THREE.AudioAnalyser( sound, 32 );
///
/// // get the average frequency of the sound
/// const data = analyser.getAverageFrequency();
/// ```
/// </summary>
[<AllowNullLiteral>]
[<Import("AudioAnalyser", "three")>]
type AudioAnalyser =
    /// <summary>Constructs a new audio analyzer.</summary>
    /// <param name="audio">The audio to analyze.</param>
    /// <param name="fftSize">The window size in samples that is used when performing a Fast Fourier Transform (FFT) to get frequency domain data.</param>
    new (audio: Audio, ?fftSize: float) = { }
    /// <summary>The global audio listener.</summary>
    member _.analyser with get () : obj = jsNative and set (_: obj) = jsNative
    /// <summary>Holds the analyzed data.</summary>
    member _.data with get () : JS.Uint8Array = jsNative and set (_: JS.Uint8Array) = jsNative
    /// <summary>
    /// Returns an array with frequency data of the audio.
    ///
    /// Each item in the array represents the decibel value for a specific frequency.
    /// The frequencies are spread linearly from 0 to 1/2 of the sample rate.
    /// For example, for 48000 sample rate, the last item of the array will represent
    /// the decibel value for 24000 Hz.
    /// </summary>
    /// <returns>The frequency data.</returns>
    member _.getFrequencyData() : JS.Uint8Array = jsNative
    /// <summary>Returns the average of the frequencies returned by AudioAnalyser#getFrequencyData.</summary>
    /// <returns>The average frequency.</returns>
    member _.getAverageFrequency() : float = jsNative

